PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS schools (id TEXT PRIMARY KEY, name TEXT NOT NULL, region TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('teacher','student','parent')), avatar_color TEXT NOT NULL DEFAULT 'green', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS users_school_idx ON users(school_id);
CREATE TABLE IF NOT EXISTS classes (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), teacher_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, grade TEXT NOT NULL, invite_code TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS classes_school_idx ON classes(school_id);
CREATE TABLE IF NOT EXISTS class_members (class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, member_role TEXT NOT NULL, joined_at TEXT NOT NULL, PRIMARY KEY(class_id,user_id));
CREATE TABLE IF NOT EXISTS guardian_links (guardian_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, relation TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(guardian_id,student_id));
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), class_id TEXT REFERENCES classes(id), owner_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, mime_type TEXT NOT NULL, size INTEGER NOT NULL, storage_key TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS materials (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), teacher_id TEXT NOT NULL REFERENCES users(id), file_id TEXT REFERENCES files(id), title TEXT NOT NULL, subject TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL, lesson_plan TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('processing','ready','failed')), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS materials_class_idx ON materials(class_id);
CREATE TABLE IF NOT EXISTS material_chunks (id TEXT PRIMARY KEY, material_id TEXT NOT NULL REFERENCES materials(id) ON DELETE CASCADE, chunk_index INTEGER NOT NULL, content TEXT NOT NULL);
CREATE VIRTUAL TABLE IF NOT EXISTS material_chunks_fts USING fts5(content, content='material_chunks', content_rowid='rowid');
CREATE TRIGGER IF NOT EXISTS material_chunks_ai AFTER INSERT ON material_chunks BEGIN INSERT INTO material_chunks_fts(rowid, content) VALUES (new.rowid, new.content); END;
CREATE TRIGGER IF NOT EXISTS material_chunks_ad AFTER DELETE ON material_chunks BEGIN INSERT INTO material_chunks_fts(material_chunks_fts, rowid, content) VALUES('delete', old.rowid, old.content); END;
CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), student_id TEXT NOT NULL REFERENCES users(id), attachment_id TEXT REFERENCES files(id), subject TEXT NOT NULL, content TEXT NOT NULL, ai_category TEXT NOT NULL, knowledge_point TEXT NOT NULL, urgency TEXT NOT NULL CHECK(urgency IN ('normal','attention')), ai_hint TEXT NOT NULL, ai_draft TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('sorting','pending','answered','published')), is_public INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS questions_class_status_idx ON questions(class_id,status);
CREATE TABLE IF NOT EXISTS answers (id TEXT PRIMARY KEY, question_id TEXT NOT NULL REFERENCES questions(id) ON DELETE CASCADE, teacher_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL, published_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assignments (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), teacher_id TEXT NOT NULL REFERENCES users(id), file_id TEXT REFERENCES files(id), title TEXT NOT NULL, subject TEXT NOT NULL, description TEXT NOT NULL, due_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','published','closed')), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS assignments_class_idx ON assignments(class_id);
CREATE TABLE IF NOT EXISTS assignment_items (id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES assignments(id) ON DELETE CASCADE, prompt TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('single','short')), options_json TEXT NOT NULL DEFAULT '[]', answer TEXT NOT NULL, points INTEGER NOT NULL, order_no INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS submissions (id TEXT PRIMARY KEY, assignment_id TEXT NOT NULL REFERENCES assignments(id) ON DELETE CASCADE, student_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL CHECK(status IN ('draft','queued','submitted','graded','revision')), score INTEGER, answers_json TEXT NOT NULL DEFAULT '{}', feedback TEXT NOT NULL DEFAULT '', submitted_at TEXT, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS submissions_student_idx ON submissions(student_id);
CREATE TABLE IF NOT EXISTS videos (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), teacher_id TEXT NOT NULL REFERENCES users(id), file_id TEXT REFERENCES files(id), title TEXT NOT NULL, description TEXT NOT NULL, knowledge_point TEXT NOT NULL, duration_seconds INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL CHECK(status IN ('processing','ready','failed')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS video_comments (id TEXT PRIMARY KEY, video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE, student_id TEXT REFERENCES users(id), anonymous_label TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS video_comments_video_idx ON video_comments(video_id);
CREATE TABLE IF NOT EXISTS video_shares (id TEXT PRIMARY KEY, video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE, teacher_id TEXT NOT NULL REFERENCES users(id), target_class_name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS video_shares_video_idx ON video_shares(video_id);
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), author_id TEXT NOT NULL REFERENCES users(id), video_id TEXT REFERENCES videos(id), type TEXT NOT NULL CHECK(type IN ('announcement','resource','question')), title TEXT NOT NULL, content TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('class','guardians')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), sender_id TEXT NOT NULL REFERENCES users(id), receiver_id TEXT REFERENCES users(id), attachment_id TEXT REFERENCES files(id), channel TEXT NOT NULL CHECK(channel IN ('class','student_teacher','parent_teacher')), content TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS messages_class_idx ON messages(class_id,created_at);
CREATE TABLE IF NOT EXISTS observations (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), student_id TEXT NOT NULL REFERENCES users(id), teacher_id TEXT NOT NULL REFERENCES users(id), category TEXT NOT NULL CHECK(category IN ('attendance','participation','cooperation','progress')), content TEXT NOT NULL, rating INTEGER NOT NULL, occurred_at TEXT NOT NULL, visible_to_guardian INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS weekly_reports (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), student_id TEXT NOT NULL REFERENCES users(id), week_start TEXT NOT NULL, summary TEXT NOT NULL, accomplishments TEXT NOT NULL, needs_help TEXT NOT NULL, family_actions TEXT NOT NULL, generated_by TEXT NOT NULL CHECK(generated_by IN ('ai','demo')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL, type TEXT NOT NULL, href TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, metadata TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS request_keys (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL);
